import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { Navigate, useNavigate, Link } from 'react-router-dom';
import { UserIcon, MapPinIcon, PhoneIcon, EnvelopeIcon, CameraIcon, ArrowLeftOnRectangleIcon, CheckCircleIcon, XCircleIcon } from '@heroicons/react/24/outline';
import axios from 'axios';

const Profile = () => {
  const { user, token, setUser, logout } = useAuth();
  const navigate = useNavigate();
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showLogoutModal, setShowLogoutModal] = useState(false);

  useEffect(() => {
    if (user) loadOrders();
    setLoading(false);
  }, [user]);

  const loadOrders = () => {
    const allOrders = JSON.parse(localStorage.getItem('farm2home_orders') || '[]');

    if (user?.userType === 'farmer') {
      // Farmers see orders where at least one of their products is present
      const farmerOrders = allOrders.filter(order => 
        order.items.some(item => item.farmerId === user.id || item.farmer?.id === user.id)
      );
      setOrders(farmerOrders.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt)));
    } else {
      // Customers see their own orders
      const customerOrders = allOrders.filter(order => order.customerId === user?.id);
      setOrders(customerOrders.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt)));
    }
  };

  const handleOrderStatus = (orderId, newStatus) => {
    const allOrders = JSON.parse(localStorage.getItem('farm2home_orders') || '[]');
    const updatedOrders = allOrders.map(order => 
      order.id === orderId ? { ...order, status: newStatus } : order
    );
    localStorage.setItem('farm2home_orders', JSON.stringify(updatedOrders));
    loadOrders(); // Refresh UI
  };

  if (!user && !loading) return <Navigate to="/login" />;

  return (
    <div className="min-h-screen bg-gray-50 py-10">
      <div className="max-w-4xl mx-auto px-4">

        {/* Profile Header */}
        <div className="bg-white rounded-2xl shadow-sm p-8 mb-8 flex justify-between items-center">
          <div className="flex items-center gap-6">
            <div className="w-20 h-20 bg-green-600 rounded-full flex items-center justify-center text-white text-3xl font-bold">
              {user?.name?.charAt(0)}
            </div>
            <div>
              <h1 className="text-2xl font-bold">{user?.name}</h1>
              <p className="text-green-600 capitalize font-medium">{user?.userType} Dashboard</p>
              <p className="text-gray-500 text-sm">{user?.address}</p>
            </div>
          </div>
          <button onClick={() => setShowLogoutModal(true)} className="text-red-500 font-semibold flex items-center gap-2">
            <ArrowLeftOnRectangleIcon className="w-5 h-5"/> Logout
          </button>
        </div>

        {/* Dynamic Section Based on User Type */}
        <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
          <div className="px-8 py-5 border-b flex justify-between items-center">
            <h2 className="text-xl font-bold text-gray-800">
              {user?.userType === 'farmer' ? 'Incoming Order Requests' : 'My Orders'}
            </h2>
          </div>

          <div className="divide-y">
            {orders.length === 0 ? (
              <div className="p-20 text-center text-gray-400">No orders found.</div>
            ) : (
              orders.map(order => (
                <div key={order.id} className="p-8 hover:bg-gray-50 transition-all">
                  <div className="flex justify-between items-start mb-4">
                    <div>
                      <span className={`text-xs font-bold uppercase px-2 py-1 rounded ${
                        order.status === 'pending' ? 'bg-yellow-100 text-yellow-700' : 
                        order.status === 'confirmed' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'
                      }`}>
                        {order.status}
                      </span>
                      <h3 className="font-bold mt-2">Order #{order.id.toString().slice(-5)}</h3>
                      <p className="text-sm text-gray-500">
                        {user?.userType === 'farmer' ? `Customer: ${order.customerName}` : `Date: ${new Date(order.createdAt).toLocaleDateString()}`}
                      </p>
                    </div>

                    {/* FARMER ACTIONS */}
                    {user?.userType === 'farmer' && order.status === 'pending' && (
                      <div className="flex gap-2">
                        <button 
                          onClick={() => handleOrderStatus(order.id, 'confirmed')}
                          className="flex items-center gap-1 bg-green-600 text-white px-4 py-2 rounded-lg text-sm font-bold"
                        >
                          <CheckCircleIcon className="w-4 h-4"/> Confirm
                        </button>
                        <button 
                          onClick={() => handleOrderStatus(order.id, 'cancelled')}
                          className="flex items-center gap-1 bg-gray-200 text-gray-700 px-4 py-2 rounded-lg text-sm font-bold"
                        >
                          <XCircleIcon className="w-4 h-4"/> Reject
                        </button>
                      </div>
                    )}

                    <div className="text-right">
                      <p className="font-bold text-lg">₹{order.total}</p>
                    </div>
                  </div>

                  <div className="bg-gray-50 p-4 rounded-xl">
                    {order.items.map((item, i) => (
                      <div key={i} className="flex justify-between text-sm py-1">
                        <span>{item.name} x {item.quantity}</span>
                        <span className="font-medium">₹{item.price * item.quantity}</span>
                      </div>
                    ))}
                  </div>
                  {user?.userType === 'farmer' && (
                    <p className="mt-4 text-sm text-gray-600 italic">Delivery Address: {order.customerAddress}</p>
                  )}
                </div>
              ))
            )}
          </div>
        </div>
      </div>

      {/* Logout Modal (Simplified) */}
      {showLogoutModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center p-4 z-50">
          <div className="bg-white p-8 rounded-2xl max-w-sm w-full text-center">
            <h2 className="text-xl font-bold mb-4">Logout?</h2>
            <div className="flex gap-4">
              <button onClick={logout} className="flex-1 bg-red-600 text-white py-2 rounded-lg">Yes</button>
              <button onClick={() => setShowLogoutModal(false)} className="flex-1 bg-gray-100 py-2 rounded-lg">Cancel</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Profile;
